//! Файл: settings/catalog/sieve.rs
//! Что делает: настройки решений 372–375 — отсев кандидата по доказанной верхней границе прибыли (core/sieve.rs). Сам
//! отсев — базовое поведение (в логике, без выключателя: отсекается только доказанное); настройки — числа: доля
//! контроля на живом боте (страховка, не доказательство) и интервал показа отсева по направлению (ревью t162, Н4).
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md).

use super::{G, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 372–377. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static SIEVE: &[SettingDef] = &[
    d("Расчёт выгодности", "sieve.audit_share", K::Decimal, L::Fraction, "доля 0–1", G, "Решения 375, 377: контроль отсева по границе на живом боте (core/sieve_audit.rs). Такая доля показанных отсечённых кандидатов (0,1 — каждый десятый, без случайности) идёт в ОБЫЧНЫЙ полный расчёт на месте кандидата — под пределом profit.calc_concurrency и сроком profit.calc_timeout_ms, с наименьшим приоритетом, котировки с меткой «audit» в сводке dex.quote_count; принят — идёт обычным путём принятого (исполнитель, окно, эпизод, карточка). Принят, и граница, пересчитанная сразу после расчёта, снова отсекает — нарушение доказательства (должно быть ноль): запись Error core.sieve_violation с расчётом и уведомление Telegram core.sieve_violation; граница уже не отсекает — данные сменились: запись Info core.sieve_audit, без Telegram. Не задана или 0 — контроля нет (отсев доказан офлайн-тестами на записанных данных)").optional(),
    d("Расчёт выгодности", "sieve.row_interval_ms", K::Integer, L::NonNegative, "мс", G, "Ревью t162, Н4 (решение 377): отсечённый границей кандидат по направлению показывается (строка «Кандидатов» в браузер, строка журнала core.candidate_sieved, закрытие эпизода, шаг доли контроля sieve.audit_share) не чаще раза в столько мс; в промежутке отсев только считается (сводка dex.quote_count, поле sieve). Любой полный расчёт направления снимает отметку — следующий отсев показывается сразу. Не задана или 0 — каждый отсев показывается (как раньше)").optional(),
];
